 let branchPrice;disk=openWorkspace(workspacePath,{clock:()=>new Date('2026-10-19T01:46:00Z')});try{const login=disk.auth.login({username:'cashier',password:'Clinic123!'}),c={token:login.token,csrf:login.csrf,role:'cashier'},manager=disk.auth.login({username:'manager',password:'Clinic123!'}),m={token:manager.token,csrf:manager.csrf,role:'manager'},assistant=disk.auth.login({username:'assistant',password:'Clinic123!'}),a={token:assistant.token,csrf:assistant.csrf,role:'assistant'};const draft=disk.prices.command(c,{action:'draft',branchId:2,serviceId:service.id,unitPriceCents:21000,validFrom:'2026-10-19T00:00:00Z',reason:'虚构二店价目',requestKey:'disk-price',commandVersion:1});branchPrice=draft.id;disk.prices.command(c,{action:'submit',branchId:2,priceId:branchPrice,expectedRevision:1,requestKey:'disk-price-submit',commandVersion:1});disk.prices.command(m,{action:'approve',branchId:2,priceId:branchPrice,expectedRevision:2,reviewNote:'虚构价目核对',requestKey:'disk-price-approve',commandVersion:1});assert.equal(disk.prices.list(c,2).prices.find(x=>x.id===branchPrice).unit_price_cents,21000);assert.ok(!disk.prices.list(c,1).prices.some(x=>x.id===branchPrice));assert.throws(()=>disk.inventory.list(a,2),/无权办理/);assert.ok(Array.isArray(disk.inventory.list(a,1).items));assert.ok(Array.isArray(disk.purchases.list(a,1).orders));assert.ok(Array.isArray(disk.resources.list(m,1).chairs));const state=disk.prepay.list(c,1,1),account=state.accounts[0],bill=account.bills.find(b=>b.items.some(i=>i.remaining_cents>0)&&b.uses.some(u=>u.remaining_cents>0)),item=bill.items.find(i=>i.remaining_cents>0),use=bill.uses.find(u=>u.remaining_cents>0);const request=disk.prepay.command(c,{action:'requestAdjustment',branchId:1,patientId:1,expectedFundsRevision:account.revision,paymentId:use.patient_payment_id,expectedPaymentRevision:use.payment_revision,billId:bill.id,expectedBillRevision:bill.revision,billItemId:item.id,expectedItemRevision:item.revision,kind:use.kind,allocationId:use.id,expectedAllocationRevision:use.revision,amountCents:1,reason:'fictional correction',evidence:'fictional evidence',requestKey:'disk-adjust',commandVersion:1});let updated=disk.prepay.list(m,1,1),submitted=updated.requests.find(r=>r.id===request.id);disk.prepay.command(m,{action:'approve',branchId:1,patientId:1,expectedFundsRevision:updated.accounts[0].revision,requestId:submitted.id,expectedRevision:submitted.revision,reviewNote:'fictional approval',requestKey:'disk-approve',commandVersion:1});updated=disk.prepay.list(c,1,1);submitted=updated.requests.find(r=>r.id===request.id);disk.prepay.command(c,{action:'refund',branchId:1,patientId:1,expectedFundsRevision:updated.accounts[0].revision,requestId:submitted.id,expectedRevision:submitted.revision,confirmed:true,recipientVerification:'fictional recipient',evidence:'fictional refund',requestKey:'disk-refund',commandVersion:1});assert.equal(disk.prepay.list(c,1,1).requests.find(r=>r.id===request.id).refunds.length,1);}finally{disk.close();}
